values ('memory-cards','Nhớ bài Tây','memory','Mã hóa mỗi lá bằng một hình trong hệ 100 số, tạo câu chuyện và nhớ chính xác thứ tự bộ bài.','club','#ef4444',true,2,ARRAY['trí nhớ','bài tây','cung điện trí nhớ'],'{"subtitle":"52 lá • Hệ hình 01–52","status":"available","totalItems":52}'::jsonb)
on conflict (id) do update set name=excluded.name,category=excluded.category,description=excluded.description,icon=excluded.icon,color=excluded.color,is_active=excluded.is_active,display_order=excluded.display_order,tags=excluded.tags,metadata=excluded.metadata,updated_at=now();

delete from public.module_groups where module_id='memory-cards';

delete from public.module_items where module_id='memory-cards';

-- Cards use the existing mnemonic images 01–52 (not 00–51).
update public.module_items as card
set attributes = card.attributes || jsonb_build_object(
  'mnemonicNumber', number_item.code,
  'mnemonicName', number_item.name,
  'mnemonicImageUrl', number_item.image_url
)
from public.module_items as number_item
where card.module_id = 'memory-cards'
  and number_item.module_id = 'numbers-00-99'
  and number_item.sort_order = card.sort_order + 1;

update public.modules
set metadata = jsonb_set(metadata, '{subtitle}', '"52 lá • Hệ hình 01–52"'::jsonb),
    updated_at = now()
where id = 'memory-cards';
